contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address x) public payable {
        require(x != address(this));
        require(x != address(c));
        uint balXBefore = c.balances(x); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        assert(balXBefore == 0 && c.balances(x) == 0 && address(c).balance == contractBalBefore);
    }
    receive() external payable {}
}

