// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address x) internal {
        vm.assume(x != address(this));
        vm.assume(x != address(c));
        uint256 balXBefore;
        try c.balances(x) returns (uint256 __r) { balXBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        try c.withdraw() {} catch { return; }
        assertTrue(balXBefore == 0 && c.balances(x) == 0 && address(c).balance == contractBalBefore);
    }

    function testFuzz_run(address x) public {
        vm.assume(x.code.length == 0 && uint160(x) > 0xffff && x != address(this) && x != address(c) && x != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && x != 0x000000000000000000636F6e736F6c652e6c6f67 && x != 0x4e59b44847b379578588920cA78FbF26c0B4956C && x != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(x);
    }

    receive() external payable {}
}
